    sealed class PickerGlyph
    {
        internal string Key,Label,Search;
        internal CommandArt Art;
    }

    static readonly Lazy<Dictionary<string,PickerGlyph>> pickerArt=new Lazy<Dictionary<string,PickerGlyph>>(ReadPickerArt);

    static Dictionary<string,PickerGlyph> ReadPickerArt()
    {
        var result=new Dictionary<string,PickerGlyph>(StringComparer.Ordinal);
        using(var stream=typeof(WpfDashboard).Assembly.GetManifestResourceStream("Fluent.Picker"))
        using(var reader=new System.IO.StreamReader(stream))
        {
            string row;
            while((row=reader.ReadLine())!=null)
            {
                string[] fields=row.Split('\t');
                string family=fields[0];
                string key="fluent:"+family;
                double size=Double.Parse(fields[1],CultureInfo.InvariantCulture);
                string label=CultureInfo.InvariantCulture.TextInfo.ToTitleCase(family.Replace('_',' '));
                string terms=family=="globe"?"website web internet":family=="link"||family=="folder_link"?"website url shortcut":
                    family.StartsWith("document",StringComparison.Ordinal)?"file notes text":family=="star"?"favorite bookmark":"";
                var shapes=new Geometry[fields.Length-3];
                for(int i=3;i<fields.Length;i++)shapes[i-3]=Shape("F1 "+fields[i],1,0,0,1,0,0);
                result.Add(key,new PickerGlyph{Key=key,Label=label,Search=label+" "+terms,Art=new CommandArt(size,size,shapes)});
            }
        }
        return result;
    }



    static bool HasDashboardGlyph(string name)
    {
        return name!=null&&(commandArt.ContainsKey(name)||(name.StartsWith("fluent:",StringComparison.Ordinal)&&pickerArt.Value.ContainsKey(name)));
    }

    static ImageSource VectorGlyph(string name,Color color){
        CommandArt art;
        if(name=="pin-active")art=filledPin;
        else if(name=="config-backup")art=configurationBackupIcon;
        else if(name=="config-restore")art=configurationRestoreIcon;
        else if(!commandArt.TryGetValue(name,out art))
        {
            PickerGlyph icon;
            art=name.StartsWith("fluent:",StringComparison.Ordinal)&&pickerArt.Value.TryGetValue(name,out icon)?icon.Art:commandArt["copy"];
        }
        var group=new DrawingGroup();group.Children.Add(new GeometryDrawing(Brushes.Transparent,null,new RectangleGeometry(new Rect(0,0,art.Width,art.Height))));
        var brush=new SolidColorBrush(color);foreach(var geometry in art.Shapes)group.Children.Add(new GeometryDrawing(brush,null,geometry));
        var image=new DrawingImage(group);image.Freeze();return image;
    }
    sealed class FluentTint : IMultiValueConverter {
        public object Convert(object[] values,Type target,object parameter,CultureInfo culture){var name=values[0] as string;var brush=values[1] as SolidColorBrush;return VectorGlyph(name??"copy",brush==null?Colors.White:brush.Color);}
